import 'package:flutter_test/flutter_test.dart';
import 'package:icon_formatter/services/packdb_db.dart';

// The "generated by the app" flag is bit 2 of the rows table and a 'fresh' key
// in the JSON store. Old rows (flags 0 or 1) must read as not fresh.
void main() {
  PackRecord rec({bool fresh = false, bool system = false}) => PackRecord(
    kind: 'original',
    id: 'app:com.example.a',
    path: '/tmp/a.png',
    label: 'A',
    package: 'com.example.a',
    activity: '',
    file: '',
    isSystem: system,
    isFresh: fresh,
  );

  Map<String, Object?> row(int flags) => {
    'kind': 'original',
    'id': 'x',
    'path': '/p.png',
    'label': 'X',
    'package': 'com.x',
    'activity': '',
    'file': '',
    'calendar_day': 0,
    'flags': flags,
  };

  test('old flag values read as not fresh', () {
    expect(PackRecord.fromRow(row(0)).isFresh, isFalse);
    expect(PackRecord.fromRow(row(1)).isFresh, isFalse);
    expect(PackRecord.fromRow(row(1)).isSystem, isTrue);
  });

  test('bit 2 reads as fresh, with or without the system bit', () {
    expect(PackRecord.fromRow(row(2)).isFresh, isTrue);
    expect(PackRecord.fromRow(row(3)).isFresh, isTrue);
    expect(PackRecord.fromRow(row(3)).isSystem, isTrue);
  });

  test('a record that is not fresh keeps its old signature', () {
    expect(rec(fresh: true).signature, isNot(rec().signature));
    expect(rec(fresh: true).signature, startsWith(rec().signature));
  });

  test('JSON store: the fresh key is written only when set, and read back', () {
    expect(rec().toJson().containsKey('fresh'), isFalse);
    final j = rec(fresh: true).toJson();
    expect(j['fresh'], isTrue);
    final back = PackRecord.fromJson('original', j)!;
    expect(back.isFresh, isTrue);
    expect(PackRecord.fromJson('original', rec().toJson())!.isFresh, isFalse);
  });
}
